touchComponent.event:
if element:parent()("scrolling"):GetInt() == 0 then playSoundFx("audio/sfx/menu_button_down.wav")
if element("quest_id"):GetInt()~=-1 then
--[[A hack for this one tutorial so the tutorial ends when you select it from the log instead of opening the log]] if element("quest_name"):GetString() == "TUT_CHALLENGE" then game.sendQuestEvent( game.MsgQuestEvent():addEvent( "open_quest", 1 ) ) else menu:popPopUp()
game.engineReceiver():Send(game.MsgStartDialog( element("quest_id"):GetInt(), element("quest_name"):GetString(), element("quest_description"):GetString(), element("quest_highlight"):GetString(), element("block_interface"):GetVectorStr(), element("unblock_interface"):GetVectorStr(), element("quest_sheetId"):GetString(), element("quest_imageId"):GetString(), element("quest_sheetIdLeft"):GetString(), element("quest_imageIdLeft"):GetString(), element("quest_sheetIdBottom"):GetString(), element("quest_imageIdBottom"):GetString()
)) end end end
